public class ObjectReader__verifySchemaType_TriageGen2Test {

    private ObjectReader objectReader;

    @Mock
    private ObjectMapper mapper;

    @Mock
    private DeserializationConfig config;

    @Mock
    private FormatSchema mockSchema;

    @Mock
    private com.fasterxml.jackson.core.format.FormatParserFactory parserFactory;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);

        // Using a protected constructor via reflection or a public entry point to instantiate
        // Since we need to control the internal _parserFactory, we will use reflection to inject it.
        objectReader = new ObjectReader(mapper, config);

        // Inject the mocked parserFactory into the objectReader instance
        // The field name is inferred from the method body: _parserFactory
        Field parserFactoryField = ObjectReader.class.getDeclaredField("_parserFactory");
        parserFactoryField.setAccessible(true);
        parserFactoryField.set(objectReader, parserFactory);
    }

    /**
     * Helper method to invoke the protected method _verifySchemaType via reflection.
     */
    private void invokeVerifySchemaType(FormatSchema schema) throws Exception {
        Method method = ObjectReader.class.getDeclaredMethod("_verifySchemaType", FormatSchema.class);
        method.setAccessible(true);
        try {
            method.invoke(objectReader, schema);
        } catch (java.lang.reflect.InvocationTargetException e) {
            // Unwrap the actual exception thrown by the method (e.g., IllegalArgumentException)
            throw (Exception) e.getCause();
        }
    }

    @Test
    public void testVerifySchemaType_WithNullSchema_DoesNothing() throws Exception {
        // Branch: if (schema != null) -> false
        invokeVerifySchemaType(null);
        // If no exception is thrown, the test passes
    }

    @Test
    public void testVerifySchemaType_WithValidSchema_DoesNothing() throws Exception {
        // Branch: if (schema != null) -> true
        // Branch: if (!_parserFactory.canUseSchema(schema)) -> false
        when(parserFactory.canUseSchema(mockSchema)).thenReturn(true);

        invokeVerifySchemaType(mockSchema);

        verify(parserFactory, times(1)).canUseSchema(mockSchema);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testVerifySchemaType_WithInvalidSchema_ThrowsException() throws Exception {
        // Branch: if (schema != null) -> true
        // Branch: if (!_parserFactory.canUseSchema(schema)) -> true
        when(parserFactory.canUseSchema(mockSchema)).thenReturn(false);
        when(parserFactory.getFormatName()).thenReturn("test-format");

        try {
            invokeVerifySchemaType(mockSchema);
        } catch (IllegalArgumentException e) {
            // Verify exception message contains expected details
            String expectedMsg = "Can not use FormatSchema of type " + mockSchema.getClass().getName() + " for format test-format";
            if (!e.getMessage().equals(expectedMsg)) {
                throw new AssertionError("Exception message mismatch. Expected: " + expectedMsg + " but got: " + e.getMessage());
            }
            throw e;
        }
    }
}
